  ('palacio', null, 'sistema', 'palacio', 'Palácio Virtual', 'O sistema interno da equipe e dos voluntários. Até 26/09 se chamava Redação.', null, '', 'https://palacio.cruzvermelhariodejaneiro.org', $j$[]$j$::jsonb, 0),
