  ('palacio.para-todos-topo-do-menu.calendario-agenda-do-palacio', 'palacio.para-todos-topo-do-menu', 'item', 'palacio', 'Calendário (agenda do Palácio)', 'Uma agenda que junta as datas de todas as áreas: pautas, publicações, voluntariado, escola, contas, frota e feriados.', 'no ar', 'Não feito (decisão registrada em docs/calendario-inteligente.md §0): IA ''Planejar o mês'', arrastar para reagendar, recorrência e sincronização de duas vias.', null, $j$[{"data":"2026-09-26","titulo":"Benchmark e proposta do calendário inteligente","detalhe":"Documento que comparou agendas de mercado e definiu o que o Palácio faria."},{"data":"2026-09-26","titulo":"Agenda com 12 camadas, alertas, link ICS e resumo semanal","detalhe":"Cada pessoa liga as camadas que quer, recebe alertas (data comemorativa sem pauta, conta vencendo), assina a agenda no celular e recebe resumo na segunda."}]$j$::jsonb, 2),
