  ('palacio.expediente.oficios-e-papel-timbrado', 'palacio.expediente', 'item', 'palacio', 'Ofícios e papel timbrado', 'Documentos oficiais numerados por ano, assinados e registrados, no papel timbrado da Cruz Vermelha.', 'no ar', '', null, $j$[{"data":"2026-09-23","titulo":"Ofícios numerados, assinados com senha e registrados no Bitcoin","detalhe":"Cada ofício recebe número do ano, assinatura e um registro verificável."},{"data":"2026-09-23","titulo":"Assinatura pelo gov.br com conferência no Palácio","detalhe":"O ofício pode ser assinado no gov.br e conferido pela página de verificação."},{"data":"2026-09-25","titulo":"Ofício no padrão visual da Cruz Vermelha","detalhe":"O PDF segue a identidade visual oficial."},{"data":"2026-09-26","titulo":"Ofícios com dados da Equipe, selo digital e texto da assinatura padrão","detalhe":"Quem assina vem da ficha de RH, o PDF leva o selo digital da filial e o texto da assinatura segue o padrão."},{"data":"2026-09-27","titulo":"Papel timbrado padrão do manual; Princípios na Área do Voluntário","detalhe":"Um só papel timbrado para todos os PDFs e a página dos Princípios Fundamentais para o voluntário."}]$j$::jsonb, 1),
  ('palacio.expediente.e-mail-do-setor', 'palacio.expediente', 'item', 'palacio', 'E-mail do setor', 'A caixa de e-mail de cada setor: ler, responder e enviar pelo endereço oficial, com a assinatura do setor.', 'no ar', '', null, $j$[{"data":"2026-09-23","titulo":"Cada setor envia pelo seu alias do Gmail com sua assinatura","detalhe":"O e-mail sai do endereço do setor, não do pessoal."},{"data":"2026-09-24","titulo":"Sincronização liga cada endereço ao setor; remetente definido no Palácio","detalhe":"A conexão com o Google é guiada e o nome do remetente é escolhido no sistema."},{"data":"2026-09-25","titulo":"Nome e assinatura de cada endereço sempre atualizados","detalhe":"Mudou no Palácio, mudou no Gmail; o quadro da assinatura cresce até o tamanho dela."},{"data":"2026-09-27","titulo":"Caixa de entrada como num cliente de e-mail","detalhe":"Receber, ler, marcar e responder dentro do Palácio."},{"data":"2026-09-28","titulo":"Leituras do Gmail guardadas por um minuto e cota tratada","detalhe":"A caixa abre mais rápido e avisa quando a cota do Google estourou."}]$j$::jsonb, 2),
