  ('palacio.pessoas.verificacao-do-candidato-a-voluntario', 'palacio.pessoas', 'item', 'palacio', 'Verificação do candidato a voluntário', 'Antes de aprovar um voluntário: identidade, antecedentes criminais, sanções (CGU) e referências, como exige a Lei 14.811/2024.', 'no ar', 'Consulta à CGU precisa da chave gratuita do Portal da Transparência em Integrações. Serpro (CPF e Datavalid) fica preparado mas desligado: é pago e exige contrato com o CNPJ da filial (ARQUITETURA §11; docs/verificacao-de-voluntarios.md §8).', null, $j$[{"data":"2026-10-02","titulo":"Verificação do candidato antes de aprovar","detalhe":"O candidato manda documento, atestado e referências por link; a coordenação confere com o Claude, consulta CEIS/CNEP/CEAF/PEP e decide: apto, apto com restrição ou não apto."},{"data":"2026-10-02","titulo":"Chave da CGU é limpa e testada antes de ir ao cofre","detalhe":"Colar o JSON do Portal da Transparência funciona; chave recusada não entra."}]$j$::jsonb, 4),
