  ('palacio.escola.escola', 'palacio.escola', 'item', 'palacio', 'Escola', 'A escola como empresa à parte: vendas da Únicopag, financeiro próprio, marketing, cursos e advertoriais.', 'no ar', '', null, $j$[{"data":"2026-09-24","titulo":"Escola 1: contas da Únicopag e o financeiro dela","detalhe":"As vendas entram pelas contas da Únicopag."},{"data":"2026-09-24","titulo":"Escola 2 e 3: marketing com campanhas, peças e anúncios do Meta","detalhe":"Campanhas, referências e linha do tempo; os anúncios do Meta entram sozinhos."},{"data":"2026-09-24","titulo":"Escola 4: advertoriais publicados como notícia","detalhe":"Matérias-anúncio da escola saem no site como notícia, com visitas e matrículas."},{"data":"2026-09-24","titulo":"Escola como empresa: menu próprio, financeiro, receita e acesso separado","detalhe":"Visão geral, Financeiro com empresas, vendas viram receita nos livros e a equipe da escola só vê a Escola."},{"data":"2026-09-27","titulo":"Marketing por curso, com alunos da Únicopag","detalhe":"Cada curso mostra quem pagou, quem tentou e não pagou e o que o marketing fez para ele."},{"data":"2026-09-28","titulo":"Cartaz de matrícula por curso, com QR","detalhe":"Em Escola → Marketing → Cursos, botão que gera o cartaz do curso com QR para a página do curso ou para a matrícula no site."}]$j$::jsonb, 0),
  ('palacio.escola.api-de-conversoes-da-meta-pagamentos-da-escola', 'palacio.escola', 'item', 'palacio', 'API de Conversões da Meta (pagamentos da Escola)', 'Cada venda paga na Únicopag vira um evento Purchase no pixel da Escola, para o Meta otimizar os anúncios.', 'feito, falta publicar ou configurar', 'Falta colar o ID do pixel e o token em Escola → Contas e integrações e clicar em Ligar (pendência R-30).', null, $j$[{"data":"2026-10-02","titulo":"Pagamentos avisados à Meta pela API de Conversões","detalhe":"O servidor manda o Purchase com categoria 'taxa_de_inscricao' ou 'curso', dados da pessoa com hash, de hora em hora; coluna 'Meta' em Vendas → Transações."}]$j$::jsonb, 1),
  ('palacio.whatsapp-e-avisos', 'palacio', 'categoria', 'palacio', 'WhatsApp e avisos', 'O número do Palácio no WhatsApp: avisos do sistema e bot para consultar e agir.', null, '', null, $j$[]$j$::jsonb, 9),
  ('palacio.whatsapp-e-avisos.whatsapp-avisos-e-bot', 'palacio.whatsapp-e-avisos', 'item', 'palacio', 'WhatsApp: avisos e bot', 'O número do Palácio no WhatsApp (Evolution API): avisos do sistema, bot para consultar e agir, fotos que viram envio e oportunidades para voluntários.', 'no ar', 'Depende de um servidor Evolution API hospedado pela filial e de um chip só do Palácio; a conexão é por QR em Configurações → WhatsApp. Quem usa verificação em duas etapas só consulta e abre chamado pelo bot (não vota nem responde).', null, $j$[{"data":"2026-09-27","titulo":"Avisos do sistema e bot pela Evolution API","detalhe":"Cada pessoa confirma o número no perfil e recebe os avisos; o bot responde 1, 2, 3."},{"data":"2026-09-27","titulo":"Fila com horário de silêncio, controle de volume e alerta de queda","detalhe":"Nada sai entre 22h e 7h; limite por minuto e por pessoa; admins são avisados quando a conexão cai."},{"data":"2026-09-27","titulo":"Bot: consultar agenda, chamados, aprovações e tirar dúvidas","detalhe":"4 agenda, 5 chamados, 6 aprovações, 'ajuda <dúvida>' busca na Central de ajuda."},{"data":"2026-09-27","titulo":"Bot: agir (responder aviso, votar, abrir chamado)","detalhe":"Responder citando o aviso manda para o lugar certo; 'aprovar' pede 'confirmo'; 'chamado:' abre um pedido."},{"data":"2026-09-27","titulo":"Fotos e vídeos mandados ao Palácio viram envio da equipe","detalhe":"Mídia enviada pelo WhatsApp abre um envio em /envios, com título e autorização de imagem."},{"data":"2026-09-27","titulo":"Voluntários recebem as oportunidades, com autorização (LGPD)","detalhe":"O voluntário confirma o número e autoriza; cada oportunidade nova é avisada uma vez."},{"data":"2026-09-27","titulo":"Correções da revisão do WhatsApp e da ficha","detalhe":"Resposta em dobro não vota duas vezes; token da ficha apagado após o envio; LGPD ao anonimizar."},{"data":"2026-09-28","titulo":"Bot pergunta os detalhes antes de abrir o chamado","detalhe":"Equipe, assunto, local, urgência e