  ('palacio.publicacao-no-site.noticias-no-site-paginas-cookies-e-pixel', 'palacio.publicacao-no-site', 'item', 'palacio', 'Notícias no site (páginas, cookies e Pixel)', 'As páginas que o Palácio publica em cruzvermelhariodejaneiro.org: notícias, medição com consentimento e pixel da Meta.', 'feito, falta publicar ou configurar', 'O código está no ar, mas as páginas das notícias só mudam depois de clicar em "Regerar as páginas das notícias" (pendência S-12, o próximo passo).', null, $j$[{"data":"2026-09-25","titulo":"Páginas das notícias no padrão da home","detalhe":"Cabeçalho, rodapé, fotos otimizadas, dados para o Google e datas que não mudam a cada edição."},{"data":"2026-09-25","titulo":"Duplicatas do 7 de Setembro redirecionam (301)","detalhe":"As duas matérias repetidas levam à certa; trilha ausente não vira aviso."},{"data":"2026-09-27","titulo":"Medição só com consentimento (LGPD) e sem convite a doar","detalhe":"GA4 e Pixel só carregam depois do aceite de cookies; políticas passam ao repositório do site; /doe/ sai das páginas."},{"data":"2026-10-02","titulo":"Pixel voltou a contar: tira o 'revoke' que travava a fila","detalhe":"Desde 28/09 o PageView tinha caído de ~200/dia para 1 a 3/dia; corrigido na home, nas 61 páginas e no modelo do Palácio."},{"data":"2026-10-02","titulo":"Notícias repassam eventos à API de Conversões, igual à home","detalhe":"Com 'sim' para marketing, o PageView sai do Pixel e do servidor com o mesmo id; quem aceitou um texto antigo é perguntado de novo."}]$j$::jsonb, 0),
