  ('palacio.administracao-e-conta.ajuda-e-tours', 'palacio.administracao-e-conta', 'item', 'palacio', 'Ajuda e tours', 'Boas-vindas, tours passo a passo, o painel ''?'' em cada tela, a Central de ajuda e os retornos do beta.', 'no ar', 'O commit de 26/09 anotou que a migração ajuda_retornos (20260929010000) não estava aplicada naquele dia; conferir em /ajuda/retornos se a caixa de retornos abre.', null, $j$[{"data":"2026-09-25","titulo":"Motor da ajuda: formato do conteúdo, registro, progresso e tour","detalhe":"A base para os tours e o texto de cada área."},{"data":"2026-09-26","titulo":"Ajuda em toda a ferramenta: boas-vindas, tours, painel '?' e Central","detalhe":"Toda tela tem ajuda; texto baixado sob demanda; correções da revisão; ajuda de Envios e Acessos."},{"data":"2026-09-26","titulo":"'Na prática', programa beta com a equipe e layout no celular","detalhe":"Histórias de uso em 40 áreas, botão 'Beta' para mandar retorno, nota por tela e 116 telas conferidas a 360 px."},{"data":"2026-09-27","titulo":"Ajuda do WhatsApp, da portaria no bot e do papel timbrado","detalhe":"Textos novos para as áreas que entraram no dia."},{"data":"2026-09-28","titulo":"Painel '?' uma coisa de cada vez e Central reordenada","detalhe":"Menos texto por vez e conteúdo na medida."}]$j$::jsonb, 1),
