  ('palacio.base-do-sistema.inteligencia-artificial-claude', 'palacio.base-do-sistema', 'item', 'palacio', 'Inteligência artificial (Claude)', 'O modelo da Anthropic que escreve textos, lê documentos e responde dúvidas dentro do Palácio.', 'no ar', '', null, $j$[{"data":"2026-09-28","titulo":"Sonnet 5 vira o modelo padrão, no lugar do Opus 5","detalhe":"Custa 2,5 vezes menos com a mesma qualidade de escrita; a variável da Vercel continua vencendo se estiver preenchida."}]$j$::jsonb, 3),
  ('site', null, 'sistema', 'site', 'Site institucional', 'O site público, a matrícula dos cursos, o portal da secretaria e o ponto da sede. Tudo na Hostinger.', null, '', 'https://cruzvermelhariodejaneiro.org', $j$[]$j$::jsonb, 1),
  ('site.matricula', 'site', 'categoria', 'site', 'Matrícula', 'A vitrine dos cursos, o pagamento da inscrição de R$ 99 e o que vem depois dele.', null, '', null, $j$[]$j$::jsonb, 0),
  ('site.matricula.matricula-cursos-presenciais-e-checkout', 'site.matricula', 'item', 'site', 'Matrícula cursos presenciais e checkout', 'Página /matricula-cursos-presenciais/ com os 7 cursos da escola e o checkout de R$ 99 (PIX ou cartão pela Unicopag), para quem quer se matricular pelo site.', 'no ar', 'Página publicada em 18/09 e checkout publicado em 18/09 (README, seções "Matrícula cursos presenciais" e "Checkout da inscrição"). Pendência: EMAIL_SECRETARIA vazio no servidor; a secretaria não recebe o aviso de inscrição paga por e-mail (README, "Pontos de atenção").', null, $j$[{"data":"2026-09-18","titulo":"Plano e briefing da matrícula rápida","detalhe":"Documentos que definem o produto: inscrição de R$ 99 em todos os cursos, dentro do domínio, com a secretaria fechando turma depois."},{"data":"2026-09-18","titulo":"Página Matrícula cursos presenciais publicada","detalhe":"Quem visita vê os 7 cursos da escola com carga horária, escolaridade, valor e inscrição de R$ 99; o catálogo é sincronizado da escola, nada é digitado à mão."},{"data":"2026-09-18","titulo":"Faixa vermelha de matrícula e bloco \"Já escolheu seu curso?\" na home","detalhe":"A home passou a levar direto à matrícula, com uma faixa acima do cabeçalho e um seletor de curso; o item \"Cursos\" saiu dos menus."},{"data":"2026-09-18","titulo":"Checkout de inscrição com PIX e cartão publicado","detalhe":"O aluno paga a inscrição no próprio site, sem sair do domínio; backend em PHP na Hostinger com e-mails pelo Resend e custos de processamento de 5% opcionais."},{"data":"2026-09-19","titulo":"Checkout com etapas, blocos numerados e resumo do curso","detalhe":"A tela de pagamento ficou mais clara: três etapas no topo, ficha do curso e total em destaque; no celular o resumo vira uma faixa compacta."},{"data":"2026-09-29","titulo":"Link longo das notas quebra dentro do cartão no celular","detalhe":"Correção visual: o link não estoura mais a largura da tela no celular."}]$j$::jsonb, 0),
  ('site.matricula.questionario-de-dias-e-horarios', 'site.matricula', 'item', 'site', 'Questionário de dias e horários', 'Depois de pagar, o aluno marca em que dias e períodos pode fazer aula; a secretaria usa as respostas para montar turmas.', 'no ar', 'No ar desde 29/09, com cron de lembretes rodando de hora em hora (README, "Questionário de dias e horários"). Pendência: EMAIL_SECRETARIA vazio; sem ele a secretaria não recebe o aviso por e-mail de cada resposta nova. A aba Horários no painel da escola está no ar desde 29/09 (docs/escola/README.md, "Fase 2").', null, $j$[{"data":"2026-09-29","titulo":"Questionário de horários: tela do aluno e aba da secretaria","detalhe":"O aluno responde pelo link pessoal da tela Parabéns; a secretaria vê um mapa por curso de quantos alunos podem em cada dia e período."},{"data":"2026-09-29","titulo":"Grade dia × período, alerta na inscrição e lembretes por e-mail","detalhe":"A tela virou uma grade de segunda a sábado por manhã, tarde e noite; quem não respondeu vê um alerta e recebe até dois lembretes, 24 h e 72 h depois do pagamento."},{"data":"2026-09-29","titulo":"Horários dos alunos também no painel da escola","detalhe":"A secretaria vê o mesmo mapa dentro da plataforma da escola, na aba Horários; a escola lê do site com uma chave, sem CPF."}]$j$::jsonb, 1),
  ('site.matricula.e-mails-e-comprovante-de-inscricao-em-pdf', 'site.matricula', 'item', 'site', 'E-mails e comprovante de inscrição em PDF', 'Os e-mails que o aluno recebe depois de pagar e o comprovante em PDF anexado, no padrão visual da filial.', 'no ar', 'No ar desde 23/09, conferido no servidor (README, "Comprovante de inscrição em PDF").', null, $j$[{"data":"2026-09-23","titulo":"Comprovante de inscrição em PDF no e-mail do aluno","detalhe":"Todo aluno que paga recebe um PDF com os dados da inscrição e do pagamento; o prazo de resposta da secretaria passou de 2 para 3 dias úteis em todo o site."},{"data":"2026-09-23","titulo":"Comprovante avisa que não substitui nota fiscal","detalhe":"Frase acrescentada no rodapé do PDF, a pedido do Matheus."}]$j$::jsonb, 2),
  ('site.secretaria', 'site', 'categoria', 'site', 'Secretaria', 'O painel que a secretaria da escola usa no dia a dia.', null, '', null, $j$[]$j$::jsonb, 1),
  ('site.secretaria.portal-da-secretaria', 'site.secretaria', 'item', 'site', 'Portal da secretaria', 'Área com login por link de e-mail onde a secretaria vê inscrições, horários, mensagens do chat, ponto da sede e comunicação.', 'no ar', 'Publicado em 30/09 junto com o ponto e a comunicação (api/painel.php está na lista scripts/publicacao-comunicacao.txt; README, "Lembretes, comunicados e opinião").', null, $j$[{"data":"2026-09-29","titulo":"Portal da secretaria com Início, Inscrições, Horários, Mensagens e Escola","detalhe":"O antigo painel virou um portal: números que pedem ação na tela inicial, filtros e busca de inscrições, ficha de cada aluno com histórico e botão \"Mandar lembrete agora\"."},{"data":"2026-09-30","titulo":"Menu do portal cabe em 1040 px e ajustes de acessibilidade","detalhe":"O último item do menu não é mais cortado; a lista de emergência usa singular e plural certos; o título recebe o foco ao trocar de tela."}]$j$::jsonb, 0),
  ('site.ponto', 'site', 'categoria', 'site', 'Ponto', 'Atalho no menu para o ponto da sede, que mora no site.', null, '', null, $j$[]$j$::jsonb, 2),
  ('site.ponto.comunicacao-do-ponto-lembretes-comunicados-e-opiniao', 'site.ponto', 'item', 'site', 'Comunicação do ponto: lembretes, comunicados e opinião', 'Lembretes automáticos (véspera, saída esquecida, aula de amanhã), comunicados da implantação e pesquisa de opinião, por e-mail e WhatsApp, controlados pela secretaria na seção Comunicação do portal.', 'feito, falta publicar ou configurar', 'Publicado em 30/09, tudo começa desligado. Para ligar: escolher o modo do WhatsApp (S-40), colocar o ponto em uso (S-41) e, se quiser o lembrete das aulas, aplicar aulas_do_dia.sql na escola (S-42).', null, $j$[{"data":"2026-09-30","titulo":"Motor de avisos, portal e páginas pessoais","detalhe":"Nasceram as tabelas, a fila de envio, os textos, a seção Comunicação do portal e as páginas pessoais (lembretes, saída informada, opinião anônima, não quero mais receber)."},{"data":"2026-09-30","titulo":"Correções das revisões de segurança, jurídico, fuso e UX","detalhe":"Várias rodadas de revisão fecharam brechas: celular só vê o necessário, opinião anônima de verdade, freios da rede da sede, prazos de guarda, reserva por e-mail perto do prazo."},{"data":"2026-09-30","titulo":"Descadastro de um clique, e-mail de reserva e lista de emergência","detalhe":"Os e-mails trazem \"cancelar inscrição\" no próprio programa de e-mail; se o WhatsApp falha de vez, sai e-mail; o portal lista quem está na sede agora para uma evacuação."},{"data":"2026-09-30","titulo":"Cota diária de e-mails e fila do WhatsApp manual","detalhe":"Os avisos usam no máximo 60 e-mails por dia para não esgotar o plano grátis da Resend, que é o mesmo da matrícula; a fila do WhatsApp abre uma aba só."},{"data":"2026-09-30","titulo":"Comunicação publicada (30/09, 15h53) com conferência e como desfazer","detalhe":"41 arquivos subiram na ordem certa, cópia do que estava no ar foi guardada e 46 verificações passaram; há script para voltar à versão anterior."},{"data":"2026-09-30","titulo":"Lista \"Para o futuro\" no guia","detalhe":"Registra o que ficou combinado para depois: QR rotativo no tablet, grupo de comparação dos lembretes, lembrete adaptativo, tela \"Hoje\" da secretaria, área do voluntário, PIN no tablet."}]$j$::jsonb, 0),
  ('site.ponto.ponto-da-sede-e-comprovante-de-comparecimento', 'site.ponto', 'item', 'site', 'Ponto da sede e comprovante de comparecimento', 'Em /ponto/, colaboradores registram chegada e saída (horas doadas) e alunos registram presença na aula e recebem comprovante em PDF; em /conferir/ qualquer pessoa confere um documento pelo código.', 'no ar', 'Publicado em 30/09 (README, "Ponto da sede", "Situação"). O que falta: imprimir o cartaz, liberar o tablet da recepção no portal e cadastrar os colaboradores; aplicar aulas_do_aluno.sql no banco da escola para o ponto dos alunos funcionar (a aplicação de 01/10 não chegou); o modelo do termo de adesão deve passar pelo jurídico antes do primeiro uso.', null, $j$[{"data":"2026-09-29","titulo":"Ponto da sede, comprovante de comparecimento e conferência pública","detalhe":"Quem chega à sede digita o CPF no tablet ou no celular (pelo QR do cartaz, a até 150 m); alunos recebem o comprovante por e-mail quando a aula termina; a secretaria vê horas, presenças e aparelhos no portal."},{"data":"2026-09-30","titulo":"Vínculo e termo de adesão do voluntário","detalhe":"Voluntários e diretoria somam horas e assinam termo de adesão (Lei 9.608/1998); empregados e terceirizados registram só presença, apagada em 90 dias; a Política de Privacidade descreve isso."},{"data":"2026-09-30","titulo":"Localização liberada no celular e limite do Wi-Fi da sede","detalhe":"O celular voltou a poder pedir a localização na página do ponto; o limite por IP deixou de travar a 16ª pessoa no Wi-Fi da sede."},{"data":"2026-09-30","titulo":"Código do dia no celular (pronto, desligado)","detalhe":"Se a secretaria ligar no portal, o celular pede também os 4 números da tela do tablet, para evitar registro por outra pessoa; começa desligado."}]$j$::jsonb, 1),
  ('site.escola', 'site', 'categoria', 'site', 'Escola', 'A ligação entre o site e a plataforma da escola.', null, '', null, $j$[]$j$::jsonb, 3),
  ('site.escola.integracao-com-a-plataforma-da-escola', 'site.escola', 'item', 'site', 'Integração com a plataforma da escola', 'Quando a inscrição é paga, o site cria a conta do aluno e a matrícula dentro da plataforma da escola (escola.cursoscruzvermelha.org) e manda o link de criar senha.', 'no ar', 'Em produção desde 28/09, com primeiro pagamento real testado de ponta a ponta (docs/escola/README.md, "Situação"). Pendência: a função aulas_do_aluno (usada pelo ponto dos alunos) não chegou ao banco da escola em 01/10; a API respondia PGRST202. Precisa rodar o arquivo inteiro de novo no SQL Editor (docs/escola/README.md, "Como ligar a consulta").', null, $j$[{"data":"2026-09-28","titulo":"Matrícula paga entra na plataforma da escola","detalhe":"O aluno sai do pagamento já com conta e matrícula na escola e recebe um botão \"Criar minha senha\"; a secretaria recebe uma linha dizendo o que aconteceu na escola."},{"data":"2026-10-01","titulo":"Scripts da escola com trava de projeto e aviso à API","detalhe":"Os arquivos SQL do ponto param se forem rodados no projeto errado e mostram no fim se a função foi criada; registra por que a aplicação de 01/10 não funcionou."}]$j$::jsonb, 0),
  ('site.paginas-do-site', 'site', 'categoria', 'site', 'Páginas do site', 'As páginas feitas à mão: home, história, idiomas, doação, cookies e políticas.', null, '', null, $j$[]$j$::jsonb, 4),
  ('site.paginas-do-site.home-contato-faq-slider-de-campanhas-e-pagina-equipe', 'site.paginas-do-site', 'item', 'site', 'Home: contato, FAQ, slider de campanhas e página Equipe', 'Blocos da página inicial (contato, FAQ com 26 perguntas, seletor de curso, slider de banners) e a página Equipe.', 'no ar', 'Home publicada em cada rodada; banner da Força-Tarefa El Niño no ar desde 02/10, 17h51 (README, "Slider de campanhas da home"). Observação do README: os textos das 11 coordenações em equipe.html foram escritos a partir do nome de cada área e pedem revisão de quem conhece cada uma.', null, $j$[{"data":"2026-09-19","titulo":"Seção de contato refeita e botão flutuante do WhatsApp removido","detalhe":"E-mail em destaque com botão copiar, sede no mapa, cartão do Instagram com 9 fotos; o botão do WhatsApp saiu."},{"data":"2026-09-19","titulo":"Seletor de curso em pílulas e bloco \"Educação salva vidas\"","detalhe":"O seletor nativo virou pílulas por curso; o bloco ganhou foto real da aula e botão para o checkout."},{"data":"2026-09-19","titulo":"FAQ da home com 20 perguntas em 4 grupos, gerada de um JSON","detalhe":"As perguntas vieram das buscas do Search Console; quem edita o JSON e roda o gerador atualiza a página e os dados estruturados."},{"data":"2026-09-20","titulo":"Verbete da Wikipédia como referência da filial","detalhe":"Link para o verbete no rodapé de todas as páginas, na FAQ e nos dados estruturados; o link do rodapé diz só \"Wikipédia\"."},{"data":"2026-09-20","titulo":"FAQ: que curso faz quem trabalha como babá ou cuidadora","detalhe":"Pergunta nova vinda dos relatórios de busca por IA."},{"data":"2026-09-27","titulo":"Equipe: e-mail de cada coordenação e da diretoria","detalhe":"Cada cartão de coordenação mostra o e-mail do setor; o mesmo vai para as páginas em inglês e espanhol."},{"data":"2026-10-02","titulo":"Banner da Força-Tarefa El Niño no slider, publicado","detalhe":"Primeiro slide da home, só informativo e sem link; página ficou mais leve (AVIF) e o servidor passou a servir .avif com o tipo certo."}]$j$::jsonb, 0),
  ('site.paginas-do-site.doacao-online-doe', 'site.paginas-do-site', 'item', 'site', 'Doação online (/doe/)', 'Página de doação dentro do domínio, com PIX ou cartão pela Unicopag, doação anônima e e-mail de agradecimento personalizado.', 'fora do ar por decisão', 'Publicada em 20/09 e tirada do ar em 25/09 a seu pedido: /doe/, /en/donate/ e /es/donar/ respondem 503 com aviso. Voltar é a decisão S-16.', null, $j$[{"data":"2026-09-20","titulo":"Página de doação em /doe/ com pagamento pela Unicopag","detalhe":"A doação saiu do subdomínio doar. (Vercel) e passou a acontecer no domínio principal; doar. virou redirecionamento."},{"data":"2026-09-20","titulo":"Doação anônima, e-mail de agradecimento personalizado e copy","detalhe":"Caixa \"Quero doar anonimamente\"; e-mail com nome, valor e o que o valor sustenta; menos menção ao meio de pagamento."},{"data":"2026-09-20","titulo":"Chave PIX do CNPJ sai do site","detalhe":"A chave foi desativada; quem quer doar por PIX passa pela página, que gera o código na hora."},{"data":"2026-09-25","titulo":"Doação online fora do ar com 503","detalhe":"As três páginas de doação mostram um aviso temporário; pagamentos já iniciados continuam sendo confirmados."}]$j$::jsonb, 1),
  ('site.paginas-do-site.site-em-ingles-e-espanhol', 'site.paginas-do-site', 'item', 'site', 'Site em inglês e espanhol', 'Versões em /en/ e /es/: institucional, FAQ, cursos, equipe, acervo, campanha do agasalho, políticas e, em inglês, as 19 notícias e a história.', 'no ar', 'Páginas EN/ES publicadas e conferidas em 21/09 (README, "Inglês e espanhol"); /en/news/ e as 19 matérias estão no sitemap atual. Pendências: os textos pedem revisão humana antes de virarem voz oficial; no Palácio Virtual, as matérias em português ainda não declaram hreflang para o inglês; decidir onde o conteúdo multilíngue vai crescer (Redação ou este repositório).', null, $j$[{"data":"2026-09-21","titulo":"Institucional e doação em /en/ e /es/, com seletor de idioma","detalhe":"Quatro páginas estáticas novas; o seletor PT · EN · ES apareceu em toda página; copy corrigida sobre doador estrangeiro (CPF obrigatório)."},{"data":"2026-09-21","titulo":"Quatro camadas: FAQ, cursos, equipe e home adensada em EN/ES","detalhe":"De 2 para 5 páginas por idioma, com FAQ adaptada (não traduzida), ficha honesta dos cursos e equipe lida da página em português."},{"data":"2026-09-27","titulo":"Notícias, Campanha do Agasalho, Privacidade, Termos e 404 em inglês","detalhe":"19 matérias traduzidas em /en/news/, cada uma apontando para a original; menu em inglês ganhou \"News\". O mesmo commit criou a primeira versão de /historia/."}]$j$::jsonb, 2),
  ('site.paginas-do-site.nossa-historia', 'site.paginas-do-site', 'item', 'site', 'Nossa história', 'Página /historia/ (e /en/history/) com a fundação da filial, o Palácio da Cruz Vermelha, a Escola de Enfermeiras, linha do tempo e fotos do acervo.', 'no ar', 'O commit 60753a5 (28/09) diz que os sitemaps com a história já estavam publicados; /historia/ e /en/history/ estão no sitemap atual, que só inclui páginas no ar. As fotos (historia-ac-*.webp) não são versionadas e subiram à parte.', null, $j$[{"data":"2026-09-27","titulo":"Página /historia/ criada, com fotos e link no menu","detalhe":"Fundação, Palácio e Escola de Enfermagem com linha do tempo; cinco fotos históricas com legenda e crédito; imagens de fundo quebradas corrigidas."},{"data":"2026-09-28","titulo":"História sem as menções ao encerramento da Escola","detalhe":"Saíram os marcos de 2000 e 2009 da linha do tempo; sitemaps regerados e publicados."},{"data":"2026-09-29","titulo":"História em formato de verbete e versão em inglês","detalhe":"Página única com presidentes até 2010, Conferência de 1935 e galerias do acervo Memória CVB; /en/history/ com hreflang entre as duas."}]$j$::jsonb, 3),
  ('site.paginas-do-site.aviso-de-cookies-e-politicas-lgpd', 'site.paginas-do-site', 'item', 'site', 'Aviso de cookies e políticas (LGPD)', 'Aviso de cookies com Rejeitar, Personalizar e Aceitar; Políticas de Privacidade, Cookies, Termos e Reembolso em PT, EN e ES; fim dos convites para doar dinheiro.', 'no ar', 'No ar desde 27/09 (o Pixel caiu a partir desse dia por causa do aviso, o que prova que estava publicado); as 12 páginas de políticas estão no sitemap atual. Pendências para a filial: nomear o encarregado quando houver; confirmar cláusulas-padrão com Google, Meta, Resend e Vercel; resposta automática em contato@ (README, "Pendências para a filial").', null, $j$[{"data":"2026-09-27","titulo":"Aviso de cookies, políticas em PT/EN/ES e fim dos convites para doar","detalhe":"GA4 e Pixel só carregam depois de \"Aceitar\"; 12 páginas de política geradas de um JSON; \"Doe\" saiu dos menus e a campanha do agasalho fala só de roupas e voluntariado."},{"data":"2026-09-27","titulo":"Impacto das Cores entra no repositório","detalhe":"A landing page do subdomínio projetocores., que vivia só na Hostinger, passou a ter histórico e ganhou aviso de cookies e políticas."}]$j$::jsonb, 4),
  ('site.paginas-do-site.pagina-de-links-da-bio-do-instagram-bio', 'site.paginas-do-site', 'item', 'site', 'Página de links da bio do Instagram (/bio/)', 'Página de links no domínio para colar na bio do Instagram, com três destinos: cursos na escola, formulário e WhatsApp do voluntariado.', 'no ar', 'Está no sitemap do site (o gerador só inclui páginas que respondem 200 no ar) e no README, "Página de links da bio do Instagram".', null, $j$[{"data":"2026-09-19","titulo":"Página /bio/ no domínio e no padrão do site","detalhe":"O link da bio sai do smartpa.ge e passa a ser medido no GA4 e no Pixel; cada clique vira evento."}]$j$::jsonb, 5),
  ('site.contato', 'site', 'categoria', 'site', 'Contato', 'Como o público fala com a filial pelo site.', null, '', null, $j$[]$j$::jsonb, 5),
  ('site.contato.chat-de-contato-por-e-mail-e-painel-de-respostas', 'site.contato', 'item', 'site', 'Chat de contato por e-mail e painel de respostas', 'Botão "Fale com a gente" em todas as páginas em português; a pessoa deixa a mensagem, recebe protocolo e a resposta vem por e-mail; a equipe responde no portal.', 'no ar', 'Conferido ao vivo em 19/09; o aviso de teste chegou na caixa do Matheus (README, "Chat de contato por e-mail"). Pendências listadas no README: filtro por assunto e CSV no painel; lembrete para contatos sem resposta em 2 dias úteis; pedir à escola as 5 perguntas do curso Lei Lucas.', null, $j$[{"data":"2026-09-19","titulo":"Chat de contato por e-mail no lugar do WhatsApp","detalhe":"Todo contato do site passou a ser por e-mail, com protocolo; o WhatsApp da secretaria saiu de botões, telas e e-mails."},{"data":"2026-09-19","titulo":"Painel de respostas e aviso de que a resposta vem por e-mail","detalhe":"A equipe responde cada contato pelo painel, com link assinado no aviso; a pessoa é avisada para onde a resposta vai e para olhar o spam."},{"data":"2026-09-21","titulo":"O chat responde na hora as dúvidas de curso","detalhe":"Antes de pedir nome e e-mail, o chat mostra a ficha do curso e botões com as dúvidas; só abre chamado para o que sobra."}]$j$::jsonb, 0),
  ('site.acervo-e-verificacao', 'site', 'categoria', 'site', 'Acervo e verificação', 'As páginas públicas que o Palácio alimenta: acervo e verificação de documentos.', null, '', null, $j$[]$j$::jsonb, 6),
  ('site.acervo-e-verificacao.acervo-publico-acervo', 'site.acervo-e-verificacao', 'item', 'site', 'Acervo público (/acervo/)', 'Parte pública do acervo da filial em /acervo/, com apresentação em PT, EN e ES; a equipe cataloga no Palácio Virtual e os itens vão para o site.', 'no ar', '', null, $j$[{"data":"2026-09-24","titulo":"Acervo público: /en/archive/, /es/acervo/, rodapé, robots e sitemaps","detalhe":"O link \"Acervo\" entrou no rodapé de 20 páginas; a apresentação está no ar sem itens."},{"data":"2026-09-24","titulo":"Cópia do site no ar para o Cloudflare R2","detalhe":"Script que guarda uma cópia completa do site no bucket do acervo, com manifesto; a primeira cópia (145 arquivos) já está lá."}]$j$::jsonb, 0),
  ('site.acervo-e-verificacao.verificacao-de-documentos-verificar', 'site.acervo-e-verificacao', 'item', 'site', 'Verificação de documentos (/verificar/)', 'Página escondida onde qualquer pessoa confere se um ofício, certificado ou comunicado da filial é autêntico, pelo código, pelo QR ou soltando o arquivo.', 'feito, falta publicar ou configurar', 'A pasta existe no repositório; no servidor ainda responde 404. Publicar escondida é a pendência S-20; abrir ao público depende da decisão R-22.', null, $j$[{"data":"2026-09-24","titulo":"Página /verificar/ pronta, escondida (lançamento oculto)","detalhe":"Sem GA4, Pixel, fontes de terceiros nem chat; testada no Chromium com 190 conferências contra uma API falsa."}]$j$::jsonb, 1),
  ('site.busca-e-medicao', 'site', 'categoria', 'site', 'Busca e medição', 'Google, Semrush, Pixel, GA4 e API de Conversões.', null, '', null, $j$[]$j$::jsonb, 7),
  ('site.busca-e-medicao.seo-sitemaps-dados-estruturados-e-auditorias', 'site.busca-e-medicao', 'item', 'site', 'SEO: sitemaps, dados estruturados e auditorias', 'Índice de sitemaps, dados estruturados, correções de 404 e redirecionamentos, auditorias do Semrush e scripts que conferem o site ao vivo.', 'no ar', 'Cada rodada foi publicada e conferida ao vivo (README, seções "Revisão de SEO", "Rodada de erros do Semrush", "Rastreabilidade"). Pendências fora deste repositório: SEO básico na escola (Render), páginas do Palácio Virtual, Perfil da Empresa no Google, pedir à nacional o link para o site. Gargalo nº 1 registrado em 23/09: criar uma página própria por curso.', null, $j$[{"data":"2026-09-19","titulo":"Sitemaps completos do domínio e novo hero da matrícula","detalhe":"Índice de sitemaps com páginas, notícias e subdomínios, conferindo cada URL ao vivo; o único endereço a enviar no Search Console."},{"data":"2026-09-19","titulo":"Imagens otimizadas, cabeçalhos completos, www→apex e 404 própria","detalhe":"Home de 11,7 MB para 2,5 MB; canonical, Open Graph e JSON-LD em todas as páginas; página 404 no padrão do site."},{"data":"2026-09-19","titulo":"Consultas do Search Console documentadas e título dos cursos alinhado","detalhe":"Título e descrição da página de cursos ajustados às buscas reais, dentro de 60 e 160 caracteres."},{"data":"2026-09-20","titulo":"404 do Search Console corrigidos e lacunas de medição listadas","detalhe":"Endereços antigos e variações sem extensão passaram a redirecionar; o README lista onde falta GA4 ou Pixel."},{"data":"2026-09-20","titulo":"Dados estruturados corrigidos, CSS minificado e llms.txt","detalhe":"Zerou os 56 erros de dados estruturados do Semrush (courseMode em Course); arquivo llms.txt diz à IA o que a filial oferece e o que não oferece."},{"data":"2026-09-20","titulo":"Rastreabilidade e links internos levados ao limite","detalhe":"Zero link interno redirecionando, zero órfã, zero 4xx; correções também nas páginas do Palácio Virtual direto no servidor."},{"data":"2026-09-23","titulo":"Revisão de SEO de 23/09 e nenhuma ligação com o domínio antigo","detalhe":"Lista dos 7 gargalos de alcance por impacto; todas as menções ao domínio antigo da filial (em disputa judicial) saíram do código."},{"data":"2026-09-27","titulo":"Sitemaps com as políticas nas três línguas, sem as páginas de doação","detalhe":"Os mapas do site acompanham o que está no ar."}]$j$::jsonb, 0),
  ('site.busca-e-medicao.velocidade-revisoes-de-conteudo-e-convencao-de-nome', 'site.busca-e-medicao', 'item', 'site', 'Velocidade, revisões de conteúdo e convenção de nome', 'Rodadas de revisão de informações e copy em todo o site, melhorias de velocidade e a regra do nome completo "Cruz Vermelha Brasileira Rio de Janeiro".', 'no ar', 'Revisão de 25/09 publicada e conferida ao vivo (README, "Revisão de erros, informações e SEO"). Fica em aberto: o telefone da secretaria continua no rodapé por coerência com o Google; decidir se sai.', null, $j$[{"data":"2026-09-19","titulo":"Nome completo da filial em todo o site","detalhe":"\"Cruz Vermelha RJ\" saiu de todo texto visível; títulos seguem \"Assunto | Cruz Vermelha Brasileira Rio de Janeiro\"."},{"data":"2026-09-19","titulo":"GA4 e Pixel adiados, Font Awesome vira SVG, fontes sem bloqueio","detalhe":"Lighthouse no celular subiu em todas as páginas (home 50→68, matrícula 39→81)."},{"data":"2026-09-23","titulo":"Prioridade certa da imagem principal e fonte sem pulo de layout","detalhe":"Home de LCP 4,2 s para 2,2 s; \"Inter Reserva\" segura o texto nas medidas da Inter enquanto a fonte carrega."},{"data":"2026-09-24","titulo":"Revisão das informações: doação mensal, vagas, turmas, valores e EN/ES","detalhe":"Promessas sem fonte saíram: doação mensal não existe, \"últimas vagas\" sem turma aberta, horário de curso errado, 1908 era da nacional."},{"data":"2026-09-25","titulo":"Revisão de erros e SEO de 25/09 publicada","detalhe":"O menu deixou de encavalar no seletor de idioma entre 1181 e 1420 px; README consolidou o que mudou no site e nas páginas do Palácio Virtual."}]$j$::jsonb, 1),
  ('site.busca-e-medicao.rastreamento-ga4-e-pixel-da-meta', 'site.busca-e-medicao', 'item', 'site', 'Rastreamento: GA4 e Pixel da Meta', 'Medição de visitas e do funil de matrícula no Google Analytics e no Pixel da Meta, com consentimento de cookies.', 'no ar', 'Correção do Pixel publicada em 02/10, 8h55, e conferida em 11 cenários (docs/rastreamento.md). Pendências: GA4 na escola e em puncaovenosav1.; Pixel nas notícias do Palácio Virtual (PR #287 do Palácio Virtual corrige o modelo; depois do merge, usar "Regerar"); conferir o segundo ID do GA4 (G-Z5NWV4RBTT).', null, $j$[{"data":"2026-09-19","titulo":"Funil padrão GA4 e Meta no checkout, Pixel na doação, agasalho e 404","detalhe":"Os eventos de comércio (view_item até purchase) alimentam os relatórios de funil; URL não muda mais ao trocar de curso, evitando page_view extra."},{"data":"2026-09-21","titulo":"Meta Pixel nas 10 páginas em inglês e espanhol","detalhe":"As páginas EN/ES tinham subido só com GA4; anúncio da Meta que caísse nelas não construía público."},{"data":"2026-09-27","titulo":"Script que separa visitas de pessoas e de robôs por país","detalhe":"Lê o GA4 pela Data API e classifica cada combinação de país, navegador e origem; precisa de conta de serviço para rodar."},{"data":"2026-10-02","titulo":"Pixel da Meta destravado (ficou sem enviar de 27/09 a 02/10)","detalhe":"Uma linha do aviso de cookies travava a fila do Pixel; PageView tinha caído de 200 para 1 a 3 por dia. Corrigido nas 61 páginas e publicado."}]$j$::jsonb, 2),
  ('site.busca-e-medicao.api-de-conversoes-da-meta', 'site.busca-e-medicao', 'item', 'site', 'API de Conversões da Meta', 'O servidor do site manda à Meta os mesmos eventos do Pixel, com o mesmo id, para medir também quem usa bloqueador e deduplicar.', 'feito, falta publicar ou configurar', 'Código publicado em 02/10. A parte do servidor fica desligada até existir api/config-meta.php com o token (pendência S-01).', null, $j$[{"data":"2026-10-02","titulo":"API de Conversões da Meta construída","detalhe":"Lead, AddPaymentInfo, Purchase, Contact e eventos de página saem pelo servidor só para quem aceitou marketing; CPF nunca vai."},{"data":"2026-10-02","titulo":"Correções da revisão adversarial e de regressões, publicadas","detalhe":"Quatro revisores acharam 11 problemas (token ia à Meta, consentimento de outra pessoa valia, sem teto global); tudo corrigido e conferido no ar às 15h37."}]$j$::jsonb, 3),
